import { Component, h, Host, Prop } from '@stencil/core';
import { __ } from '@wordpress/i18n';

import { OrderShipmentStatus } from '../../../types';

const status = {
  unshipped: __('Not Shipped', 'surecart'),
  shipped: __('Shipped', 'surecart'),
  partially_shipped: __('Partially Shipped', 'surecart'),
  delivered: __('Delivered', 'surecart'),
  label_purchased: __('Label Purchased', 'surecart'),
  in_transit: __('In Transit', 'surecart'),
} as {
  [key in OrderShipmentStatus]: string;
};

// Customer-facing overrides for statuses whose default (merchant) wording is too technical.
const customerStatus = {
  label_purchased: __('Preparing to Ship', 'surecart'),
} as Partial<{
  [key in OrderShipmentStatus]: string;
}>;

const type = {
  unshipped: 'default',
  shipped: 'info',
  partially_shipped: 'warning',
  delivered: 'success',
  label_purchased: 'info',
  in_transit: 'warning',
} as {
  [key in OrderShipmentStatus]: 'default' | 'success' | 'warning' | 'danger' | 'info';
};

@Component({
  tag: 'sc-order-shipment-badge',
  styleUrl: 'sc-order-shipment-badge.css',
  shadow: true,
})
export class ScOrderShipmentBadge {
  /** The tag's statux type. */
  @Prop() status: OrderShipmentStatus;

  /** Where the badge is shown. 'customer' applies friendlier wording for some statuses. */
  @Prop() context: 'admin' | 'customer' = 'admin';

  /** The tag's size. */
  @Prop({ reflect: true }) size: 'small' | 'medium' | 'large' = 'medium';

  /** Draws a pill-style tag with rounded edges. */
  @Prop({ reflect: true }) pill: boolean = false;

  /** Makes the tag clearable. */
  @Prop() clearable: boolean = false;

  /** Resolve the visible label, applying customer-friendly overrides in the customer context. */
  getLabel(): string {
    if (this.context === 'customer' && customerStatus[this.status]) {
      return customerStatus[this.status];
    }
    return status[this.status] || this.status;
  }

  render() {
    // don't render if not shippable.
    if (this.status === 'unshippable') {
      return <Host style={{ display: 'none' }}></Host>;
    }

    return (
      <sc-tag type={type?.[this?.status]} pill={this.pill}>
        {this.getLabel()}
      </sc-tag>
    );
  }
}
